import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [exportLoading, setExportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("users");
  const [newCandidate, setNewCandidate] = useState({
    name: "",
    party: "",
    symbol: "",
    description: "",
  });

  useEffect(() => {
    const token = localStorage.getItem("adminToken");
    if (!token) {
      navigate("/admin-login");
      return;
    }
    fetchUsers();
    fetchCandidates();
    fetchResults();
  }, [navigate]);

  const fetchUsers = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.get("http://localhost:5000/api/users", {
        headers: { Authorization: token },
      });
      setUsers(response.data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching users:", error);
      if (error.response?.status === 401) {
        localStorage.removeItem("adminToken");
        navigate("/admin-login");
      }
      setLoading(false);
    }
  };

  const fetchCandidates = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/candidates");
      if (response.data.success) setCandidates(response.data.candidates);
    } catch (error) {
      console.error("Error fetching candidates:", error);
    }
  };

  const fetchResults = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.get(
        "http://localhost:5000/api/election-results",
        {
          headers: { Authorization: token },
        }
      );
      if (response.data.success) setResults(response.data.results);
    } catch (error) {
      console.error("Error fetching results:", error);
    }
  };

  const addCandidate = async () => {
    if (!newCandidate.name || !newCandidate.party) {
      alert("Please fill name and party fields");
      return;
    }

    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.post(
        "http://localhost:5000/api/candidates",
        newCandidate,
        {
          headers: { Authorization: token },
        }
      );

      if (response.data.success) {
        alert("Candidate added successfully!");
        setNewCandidate({ name: "", party: "", symbol: "", description: "" });
        fetchCandidates();
        fetchResults();
      }
    } catch (error) {
      console.error("Error adding candidate:", error);
      alert(
        "Failed to add candidate: " +
          (error.response?.data?.message || error.message)
      );
    }
  };

  const exportToExcel = async () => {
    try {
      setExportLoading(true);
      const token = localStorage.getItem("adminToken");
      const response = await axios.get(
        "http://localhost:5000/api/export-excel",
        {
          headers: { Authorization: token },
          responseType: "blob",
        }
      );

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `ElectionData_${new Date().getTime()}.xlsx`
      );
      document.body.appendChild(link);
      link.click();
      link.remove();

      alert("✅ Excel file downloaded successfully!");
    } catch (error) {
      console.error("Error exporting Excel:", error);
      alert(
        "❌ Error exporting Excel file: " +
          (error.response?.data?.message || error.message)
      );
    } finally {
      setExportLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("adminToken");
    navigate("/admin-login");
  };

  const goToUserLogin = () => {
    navigate("/login");
  };

  const viewFaceImage = (faceImage) => {
    if (faceImage) {
      const imageUrl = `http://localhost:5000/uploads/${faceImage}`;
      window.open(imageUrl, "_blank");
    }
  };

  if (loading) return <div className="loading">Loading data...</div>;

  return (
    <div className="admin-dashboard">
      <div className="dashboard-header">
        <div>
          <h1>👨‍💼 E-Voting Admin Dashboard</h1>
          <p>Manage elections, candidates, and monitor voting</p>
        </div>
        <div className="header-actions">
          <button onClick={goToUserLogin} className="user-login-btn">
            👤 User Login
          </button>
          <button onClick={handleLogout} className="logout-btn">
            🚪 Logout
          </button>
        </div>
      </div>

      <div className="dashboard-stats">
        <div className="stat-card total-users">
          <h3>Total Verified Users</h3>
          <p>{users.length}</p>
        </div>
        <div className="stat-card today-users">
          <h3>Votes Cast</h3>
          <p>{users.filter((user) => user.has_voted).length}</p>
        </div>
        <div className="stat-card unique-voters">
          <h3>Candidates</h3>
          <p>{candidates.length}</p>
        </div>
        <div className="stat-card pending-votes">
          <h3>Voting %</h3>
          <p>
            {users.length > 0
              ? Math.round(
                  (users.filter((user) => user.has_voted).length /
                    users.length) *
                    100
                )
              : 0}
            %
          </p>
        </div>
      </div>

      <div className="dashboard-tabs">
        <button
          className={`tab-button ${activeTab === "users" ? "active" : ""}`}
          onClick={() => setActiveTab("users")}
        >
          👥 Users
        </button>
        <button
          className={`tab-button ${activeTab === "candidates" ? "active" : ""}`}
          onClick={() => setActiveTab("candidates")}
        >
          🗳️ Candidates
        </button>
        <button
          className={`tab-button ${activeTab === "results" ? "active" : ""}`}
          onClick={() => setActiveTab("results")}
        >
          📊 Results
        </button>
      </div>

      <div className="dashboard-actions">
        <button
          onClick={exportToExcel}
          className="export-btn"
          disabled={users.length === 0 || exportLoading}
        >
          {exportLoading ? "📊 Exporting..." : `📊 Export to Excel`}
        </button>
        <button
          onClick={() => {
            fetchUsers();
            fetchCandidates();
            fetchResults();
          }}
          className="refresh-btn"
        >
          🔄 Refresh Data
        </button>
      </div>

      {activeTab === "users" &&
        (users.length === 0 ? (
          <div className="no-data">
            <h3>📭 No user verification data found</h3>
            <p>Users will appear here after they complete verification.</p>
          </div>
        ) : (
          <div className="users-table-container">
            <table className="users-table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Aadhar</th>
                  <th>Phone</th>
                  <th>Voter ID</th>
                  <th>Email</th>
                  <th>Wallet</th>
                  <th>Face Image</th>
                  <th>Voted</th>
                  <th>Timestamp</th>
                </tr>
              </thead>
              <tbody>
                {users.map((user) => (
                  <tr key={user.ID || user.id}>
                    <td>{user.ID || user.id}</td>
                    <td>{user.name}</td>
                    <td>{user.aadhar_number || user.aadhaar_number}</td>
                    <td>{user.phone_number}</td>
                    <td>{user.voterid || user.voter_id}</td>
                    <td>{user.email}</td>
                    <td className="wallet-address" title={user.wallet_address}>
                      {user.wallet_address
                        ? `${user.wallet_address.slice(
                            0,
                            6
                          )}...${user.wallet_address.slice(-4)}`
                        : "N/A"}
                    </td>
                    <td>
                      {user.face_image ? (
                        <button
                          className="view-image-btn"
                          onClick={() => viewFaceImage(user.face_image)}
                        >
                          📷 View
                        </button>
                      ) : (
                        "❌"
                      )}
                    </td>
                    <td>
                      <span
                        className={`vote-status ${
                          user.has_voted ? "voted" : "not-voted"
                        }`}
                      >
                        {user.has_voted ? "✅ Yes" : "❌ No"}
                      </span>
                    </td>
                    <td>{new Date(user.timestamp).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ))}

      {activeTab === "candidates" && (
        <div className="candidates-section">
          <div className="add-candidate-form">
            <h3>Add New Candidate</h3>
            <div className="form-row">
              <input
                type="text"
                placeholder="Candidate Name"
                value={newCandidate.name}
                onChange={(e) =>
                  setNewCandidate({ ...newCandidate, name: e.target.value })
                }
                className="form-input"
              />
              <input
                type="text"
                placeholder="Party"
                value={newCandidate.party}
                onChange={(e) =>
                  setNewCandidate({ ...newCandidate, party: e.target.value })
                }
                className="form-input"
              />
            </div>
            <div className="form-row">
              <input
                type="text"
                placeholder="Symbol (Optional)"
                value={newCandidate.symbol}
                onChange={(e) =>
                  setNewCandidate({ ...newCandidate, symbol: e.target.value })
                }
                className="form-input"
              />
              <input
                type="text"
                placeholder="Description (Optional)"
                value={newCandidate.description}
                onChange={(e) =>
                  setNewCandidate({
                    ...newCandidate,
                    description: e.target.value,
                  })
                }
                className="form-input"
              />
            </div>
            <button onClick={addCandidate} className="add-candidate-btn">
              ➕ Add Candidate
            </button>
          </div>

          <div className="candidates-list">
            <h3>Current Candidates</h3>
            {candidates.length === 0 ? (
              <div className="no-data">No candidates added yet</div>
            ) : (
              <div className="candidates-grid">
                {candidates.map((candidate) => (
                  <div key={candidate.id} className="candidate-card">
                    <h4>{candidate.name}</h4>
                    <p className="party">{candidate.party}</p>
                    {candidate.symbol && (
                      <p className="symbol">Symbol: {candidate.symbol}</p>
                    )}
                    {candidate.description && (
                      <p className="description">{candidate.description}</p>
                    )}
                    <p className="status">
                      Active: {candidate.is_active ? "Yes" : "No"}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === "results" && (
        <div className="results-section">
          <h3>Election Results</h3>
          {results.length === 0 ? (
            <div className="no-data">No results available yet</div>
          ) : (
            <div className="results-table-container">
              <table className="results-table">
                <thead>
                  <tr>
                    <th>Rank</th>
                    <th>Candidate</th>
                    <th>Party</th>
                    <th>Votes</th>
                    <th>Percentage</th>
                  </tr>
                </thead>
                <tbody>
                  {results
                    .sort((a, b) => b.voteCount - a.voteCount)
                    .map((candidate, index) => {
                      const totalVotes = results.reduce(
                        (sum, c) => sum + parseInt(c.voteCount),
                        0
                      );
                      const percentage =
                        totalVotes > 0
                          ? ((candidate.voteCount / totalVotes) * 100).toFixed(
                              2
                            )
                          : 0;

                      return (
                        <tr key={candidate.id}>
                          <td>
                            {index === 0
                              ? "🥇"
                              : index === 1
                              ? "🥈"
                              : index === 2
                              ? "🥉"
                              : index + 1}
                          </td>
                          <td>{candidate.name}</td>
                          <td>{candidate.party}</td>
                          <td>{candidate.voteCount}</td>
                          <td>{percentage}%</td>
                        </tr>
                      );
                    })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
